#!/usr/bin/env node
// Generates the wiki UI that runs INSIDE the NooblyJS frame from the standalone one.
//
//   node scripts/port-wiki-ui.mjs            (npm run port:ui)
//
// The standalone UI (src/web/wiki/public, plus the shared files in public/js/markdown) is a page of its own: it
// has its own <html>, loads libraries from CDNs, calls absolute URLs (/applications/wiki/api/…), drives the
// address bar with pushState and listens on Socket.IO. None of that is allowed in the frame, where there is one
// document, one router and one content security policy (script-src 'self'). Rather than fork ~60 modules by hand,
// this applies the same handful of mechanical changes to every file, so the standalone UI keeps working from the
// same source until it is retired. THE OUTPUT IS GENERATED: change the source or this script, never the output.
//
//   src/web/wiki/public/js|images|data   →  public/app/…          URLs rewritten, browser globals → __wikiEnv
//   src/web/wiki/public/index.html       →  public/app/markup.js  the <body> markup, as a string
//                                           public/app/inline.js  its inline scripts
//   public/js/markdown/*.js              →  public/app/shared/…
//   the page's stylesheets + Bootstrap   →  public/css/wiki-app.css, every selector under [data-module="wiki"]
//   Bootstrap, marked, Prism (from npm)  →  public/vendor/…
//   src/web/datasources/public/js        →  public/app/ds/…        the datasources screens, the same way
//   its stylesheet + CodeMirror          →  public/css/wiki-ds.css, every selector under [data-module="wiki"] .ds-root
//
// What the frame needs that a text rewrite cannot give lives in two hand-written files: public/js/hosted/env.js
// (`__wikiEnv`: fetch with the CSRF token, the location/history facade over the URL hash, the event stream) and
// public/js/pages/wiki.js (the page that puts the markup into the frame and starts the app).
//
// The mount path is baked into the output (URL literals appear inside HTML strings, where nothing can resolve them
// at run time). The server works under any mount path; for another one, run this with --mount.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const { scopeCss } = require('nooblyjs-core/src/shell/css-scope.js');

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const at = process.argv.indexOf('--mount');
const MOUNT = at === -1 ? '/wiki' : process.argv[at + 1];
const NAME = 'wiki';
const SRC = path.join(ROOT, 'src/web/wiki/public');
const PUBLIC = path.join(ROOT, 'public');
const OUT = path.join(PUBLIC, 'app');
const NM = path.join(ROOT, 'node_modules');
const BANNER = '// GENERATED by scripts/port-wiki-ui.mjs — do not edit. Source: ';

/** Absolute URLs of the standalone app → where the same thing lives under the mount path. Order matters. */
function rewriteUrls(text) {
  return text
    .replaceAll('/applications/wiki/api', `${MOUNT}/api/v1`)
    .replace(/\/applications\/wiki\/(avatars|media)\b/g, `${MOUNT}/$1`)
    .replace(/\/applications\/wiki\/(js|images|data)\//g, `${MOUNT}/app/$1/`)
    .replaceAll('/applications/wiki', MOUNT)
    // Libraries the editor and parser fetch on demand: from this app's copies (the frame allows no CDN).
    .replaceAll('https://cdn.jsdelivr.net/gh/highlightjs/cdn-release@11.9.0/build/', `${MOUNT}/vendor/highlightjs/`)
    .replaceAll('https://cdn.jsdelivr.net/npm/mermaid@10/dist/', `${MOUNT}/vendor/mermaid/`)
    .replace(/(['"`(=])\/api\//g, `$1${MOUNT}/api/v1/ds/`)
    .replace(/(['"`(=])\/js\/markdown\//g, `$1${MOUNT}/app/shared/`)
    .replace(/(['"`(=])\/(images|css)\//g, `$1${MOUNT}/$2/`);
}

/** Browser globals a hosted page may not use directly → the same call on __wikiEnv (public/js/hosted/env.js). */
function rewriteGlobals(code) {
  return code
    .replace(/\b(?:window|document)\.location\b/g, '__wikiEnv.location')
    .replace(/(?<![\w.$])location\.(pathname|href|search|hash|origin|host|hostname|protocol|reload|replace|assign)\b/g, '__wikiEnv.location.$1')
    .replace(/\bwindow\.history\b/g, '__wikiEnv.history')
    .replace(/(?<![\w.$])history\.(pushState|replaceState|back|forward|go|state|length)\b/g, '__wikiEnv.history.$1')
    .replace(/\bwindow\.addEventListener\(\s*(['"])popstate\1\s*,/g, '__wikiEnv.onPopState(')
    .replace(/\bdocument\.addEventListener\(\s*(['"])DOMContentLoaded\1\s*,/g, '__wikiEnv.onReady(')
    // Page-wide listeners stay bound while the person is in another NooblyJS app (the wiki's DOM is kept, not rebuilt),
    // so they go through the env, which holds them back until the wiki is on screen again.
    .replace(/\b(window|document)\.(addEventListener|removeEventListener)\(/g, '__wikiEnv.$1Events.$2(')
    .replace(/\bwindow\.fetch\(/g, '__wikiEnv.fetch(')
    .replace(/(?<![\w.$])fetch\(/g, '__wikiEnv.fetch(')
    .replace(/\bnew XMLHttpRequest\b/g, 'new __wikiEnv.XMLHttpRequest')
    .replace(/(?<![\w.$])io\(/g, '__wikiEnv.io(')
    .replace(/\bdocument\.body\.(appendChild|removeChild|insertAdjacentHTML|append|prepend)\b/g, '__wikiEnv.portal.$1');
}

const rel = (file) => path.relative(ROOT, file).replaceAll('\\', '/');
// --check writes nothing: it lists the generated files that are missing or differ from what would be written.
const CHECK = process.argv.includes('--check');
const stale = [];
const same = (file, content) => fs.existsSync(file) && Buffer.compare(fs.readFileSync(file), Buffer.from(content)) === 0;
const write = (file, content) => {
  if (CHECK) {
    if (!same(file, content)) stale.push(rel(file));
    return;
  }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
};
const copy = (from, to) => write(to, fs.readFileSync(from));
function* walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else yield full;
  }
}

if (!CHECK) {
  fs.rmSync(OUT, { recursive: true, force: true });
  fs.rmSync(path.join(PUBLIC, 'vendor'), { recursive: true, force: true });
}
const counts = { js: 0, copied: 0 };

// ---------------------------------------------------------------- the app's own files
// Left out: the Teams/iframe embedding shim and the first-run wizard page (both are pages of their own).
const SKIP = new Set(['js/embed-bootstrap.js', 'js/wizard.js']);
for (const sub of ['js', 'images', 'data']) {
  for (const file of walk(path.join(SRC, sub))) {
    const within = path.relative(SRC, file).replaceAll('\\', '/');
    if (SKIP.has(within)) continue;
    const target = path.join(OUT, within);
    // Third-party bundles (pdf.js) are copied as they are.
    if (!within.endsWith('.js') || within.startsWith('js/vendor/')) {
      copy(file, target);
      counts.copied++;
      continue;
    }
    write(target, `${BANNER}${rel(file)}\n${rewriteGlobals(rewriteUrls(fs.readFileSync(file, 'utf8')))}`);
    counts.js++;
  }
}
for (const name of ['markdown-editor.js', 'markdown-editor-blocks.js', 'markdown-parser.js']) {
  const file = path.join(PUBLIC, 'js/markdown', name);
  write(path.join(OUT, 'shared', name), `${BANNER}${rel(file)}\n${rewriteGlobals(rewriteUrls(fs.readFileSync(file, 'utf8')))}`);
  counts.js++;
}

// ---------------------------------------------------------------- the page: markup and inline scripts
const page = fs.readFileSync(path.join(SRC, 'index.html'), 'utf8');
const body = page.slice(page.indexOf('>', page.indexOf('<body')) + 1, page.lastIndexOf('</body>'));
const inline = [];
let markup = body.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/g, (match, attrs, code) => {
  if (!/\bsrc=/.test(attrs) && code.trim()) inline.push(code);
  return '';
});
// The one inline handler: the frame's policy runs no inline script, so the page binds it (pages/wiki.js).
markup = markup.replace(/\sonclick="window\.wikiApp && window\.wikiApp\.showHome\(\)"/, ' data-wk-action="home"');
if (/\son[a-z]+="/.test(markup)) throw new Error('index.html has an inline event handler this script does not know: the frame would silently drop it.');
write(path.join(OUT, 'markup.js'), `${BANNER}src/web/wiki/public/index.html (<body>)\nexport default ${JSON.stringify(rewriteUrls(markup))};\n`);
write(path.join(OUT, 'inline.js'), `${BANNER}src/web/wiki/public/index.html (inline scripts)\n${inline.map((code, i) => `// ---- inline script ${i + 1}\n{\n${rewriteGlobals(rewriteUrls(code))}\n}`).join('\n')}\n`);

// ---------------------------------------------------------------- libraries the page took from CDNs
const VENDOR = path.join(PUBLIC, 'vendor');
copy(path.join(NM, 'bootstrap/dist/js/bootstrap.bundle.min.js'), path.join(VENDOR, 'bootstrap/bootstrap.bundle.min.js'));
copy(path.join(NM, 'marked/marked.min.js'), path.join(VENDOR, 'marked/marked.min.js'));
copy(path.join(NM, 'prismjs/components/prism-core.min.js'), path.join(VENDOR, 'prism/components/prism-core.min.js'));
copy(path.join(NM, 'prismjs/plugins/autoloader/prism-autoloader.min.js'), path.join(VENDOR, 'prism/plugins/autoloader/prism-autoloader.min.js'));
for (const file of fs.readdirSync(path.join(NM, 'prismjs/components'))) {
  if (file.endsWith('.min.js')) copy(path.join(NM, 'prismjs/components', file), path.join(VENDOR, 'prism/components', file));
}
copy(path.join(NM, '@highlightjs/cdn-assets/highlight.min.js'), path.join(VENDOR, 'highlightjs/highlight.min.js'));
copy(path.join(NM, 'mermaid/dist/mermaid.min.js'), path.join(VENDOR, 'mermaid/mermaid.min.js'));
// Two stylesheets are loaded by the editor itself, with a <link> beside its own script: scoped copies go where it
// looks for them.
const scopedCopy = (from, to) => write(to, `/* GENERATED by scripts/port-wiki-ui.mjs — do not edit. Source: ${rel(from)} */\n${scopeCss(rewriteUrls(fs.readFileSync(from, 'utf8')), NAME)}\n`);
scopedCopy(path.join(NM, '@highlightjs/cdn-assets/styles/atom-one-dark.min.css'), path.join(VENDOR, 'highlightjs/styles/atom-one-dark.min.css'));
scopedCopy(path.join(PUBLIC, 'js/markdown/markdown-editor.css'), path.join(OUT, 'shared/markdown-editor.css'));
for (const font of ['bootstrap-icons.woff2', 'bootstrap-icons.woff']) copy(path.join(NM, 'bootstrap-icons/font/fonts', font), path.join(VENDOR, 'bootstrap-icons', font));

// ---------------------------------------------------------------- one scoped stylesheet
const sheets = [
  path.join(NM, 'prismjs/themes/prism-tomorrow.min.css'),
  path.join(NM, 'bootstrap/dist/css/bootstrap.min.css'),
  path.join(NM, 'bootstrap-icons/font/bootstrap-icons.min.css'),
  path.join(PUBLIC, 'css/styles.css'),
  path.join(SRC, 'css/onboarding.css'),
  path.join(SRC, 'css/wiki.css'),
];
const dropped = [];
const css = sheets.map((file) => `/* ---- ${rel(file)} ---- */\n${fs.readFileSync(file, 'utf8').replace(/\/\*# sourceMappingURL=.*?\*\//g, '')}`).join('\n\n');
const scoped = scopeCss(rewriteUrls(css), NAME, { onDropped: (text) => dropped.push(text.replace(/\s+/g, ' ').slice(0, 70)) });
// scopeCss drops every @font-face (text fonts are the kit's). The icon font is not a text font: without it every
// <i class="bi …"> is an empty box, so it is declared here, from this app's own copy.
const iconFont = `@font-face { font-display: block; font-family: "bootstrap-icons"; src: url("../vendor/bootstrap-icons/bootstrap-icons.woff2") format("woff2"), url("../vendor/bootstrap-icons/bootstrap-icons.woff") format("woff"); }`;
write(path.join(PUBLIC, 'css/wiki-app.css'), `/* GENERATED by scripts/port-wiki-ui.mjs — do not edit. Sources:\n${sheets.map((f) => `   ${rel(f)}`).join('\n')} */\n${iconFont}\n${scoped}\n`);

// ---------------------------------------------------------------- the datasources screens
// The second standalone page (src/web/datasources/public: workflows, schedules, runs, spaces, repositories, agents,
// prompts, user activity, settings) gets the same treatment, into public/app/ds. Only the scripts its index.html
// loads are ported, in that order (public/app/ds/scripts.js): the folder also holds an older generation of screens
// the page no longer uses. Left out: the Teams shim, and app.js, which is the UIService shell (header, sidebar,
// sign-in) the frame draws instead; public/js/pages/datasources.js starts the screens in its place.
const DS_SRC = path.join(ROOT, 'src/web/datasources/public');
const DS_OUT = path.join(OUT, 'ds');
const DS_SKIP = new Set(['js/embed-bootstrap.js', 'js/app.js']);
// Its page-wide listeners and dialogs go to the env's `ds` part, so they are held apart from the wiki's.
const forDs = (code) => rewriteGlobals(rewriteUrls(code)).replace(/__wikiEnv\.(windowEvents|documentEvents|portal)\b/g, '__wikiEnv.ds.$1');
const dsScripts = [...fs.readFileSync(path.join(DS_SRC, 'index.html'), 'utf8').matchAll(/<script src="(js\/[^"?]+)/g)].map((m) => m[1]).filter((src) => !DS_SKIP.has(src));
if (dsScripts.length < 20) throw new Error('src/web/datasources/public/index.html no longer lists its scripts the way this script reads them.');
for (const within of dsScripts) {
  const file = path.join(DS_SRC, within);
  write(path.join(DS_OUT, within), `${BANNER}${rel(file)}\n${forDs(fs.readFileSync(file, 'utf8'))}`);
  counts.js++;
}
write(path.join(DS_OUT, 'scripts.js'), `${BANNER}src/web/datasources/public/index.html (its <script> tags, in order)\nexport default ${JSON.stringify(dsScripts, null, 2)};\n`);
// CodeMirror 5 (the step and code editors), which the page took from a CDN.
for (const file of ['lib/codemirror.js', 'mode/javascript/javascript.js', 'addon/hint/show-hint.js', 'addon/hint/javascript-hint.js']) {
  copy(path.join(NM, 'codemirror', file), path.join(VENDOR, 'codemirror', file));
}
// Its stylesheet is a second file, and every rule is held under `.ds-root` (the element pages/datasources.js draws
// into, and the env's ds portal) as well as the app's scope: it restyles class names the wiki also uses (.btn,
// .hidden, .page-title, .sidebar, …), and both sets of pages share one [data-module="wiki"].
const dsSheets = [
  path.join(NM, 'codemirror/lib/codemirror.css'),
  path.join(NM, 'codemirror/theme/monokai.css'),
  path.join(NM, 'codemirror/addon/hint/show-hint.css'),
  path.join(DS_SRC, 'css/datasources.css'),
];
const dsCss = dsSheets.map((file) => `/* ---- ${rel(file)} ---- */\n${fs.readFileSync(file, 'utf8').replace(/\/\*# sourceMappingURL=.*?\*\//g, '')}`).join('\n\n');
const dsScoped = scopeCss(rewriteUrls(dsCss), NAME, { onDropped: (text) => dropped.push(text.replace(/\s+/g, ' ').slice(0, 70)) })
  .replaceAll(`[data-module="${NAME}"]`, `[data-module="${NAME}"] .ds-root`);
write(path.join(PUBLIC, 'css/wiki-ds.css'), `/* GENERATED by scripts/port-wiki-ui.mjs — do not edit. Sources:\n${dsSheets.map((f) => `   ${rel(f)}`).join('\n')} */\n${dsScoped}\n`);

if (CHECK) {
  if (stale.length) {
    console.error(`The generated wiki UI is out of date (run: npm run port:ui):\n  ${stale.slice(0, 20).join('\n  ')}${stale.length > 20 ? `\n  … and ${stale.length - 20} more` : ''}`);
    process.exit(1);
  }
  console.log('The generated wiki UI is up to date.');
  process.exit(0);
}
console.log(`ported the wiki UI for mount path ${MOUNT}: ${counts.js} scripts rewritten (${dsScripts.length} of them the datasources screens), ${counts.copied} files copied, ${inline.length} inline scripts, ${(scoped.length / 1024).toFixed(0)} + ${(dsScoped.length / 1024).toFixed(0)} KB of scoped CSS`);
if (dropped.length) console.log(`dropped from the CSS (fonts and imports belong to the kit):\n  ${[...new Set(dropped)].join('\n  ')}`);
